# -*- coding: utf-8 -*-
# 第 10 批（D3）：水污染防治措施及檢測申報管理辦法 第70條之1～第89條
W = "ENV-09"
Q = [

(W,"第70條之1",3,"水措-沼液申請",
 "沼液沼渣農地肥分使用者應向何機關申請？經審查同意後應如何辦理？",
 ["應檢具沼液沼渣農地肥分使用計畫向農業主管機關申請，經審查同意後報直轄市、縣（市）環保主管機關備查並依登記事項運作","應檢具沼液沼渣農地肥分使用計畫向環保主管機關申請，經審查同意後報直轄市、縣（市）農業主管機關備查並依登記事項運作","應檢具沼液沼渣農地肥分使用計畫向農業主管機關報備，經備查完成後報中央主管機關核准並公告後始得依登記事項運作","應檢具沼液沼渣農地肥分使用計畫向水利主管機關申請，經審查同意後報直轄市、縣（市）環保主管機關備查並依核定運作"],"a",
 "第70條之1第1項：沼液沼渣農地肥分使用者應檢具沼液沼渣作為農地肥分使用計畫，向農業主管機關提出申請，經農業主管機關審查同意後，報直轄市、縣（市）環保主管機關備查，並依登記事項運作。第2項：農業主管機關審查時應邀請環保主管機關參與審查，必要時應現場勘查。",
 "To whom is a biogas slurry land application plan submitted, and what follows approval?",
 ["Apply to the agriculture authority; after its approval file with the municipal or county environmental authority and operate as registered","Apply to the environmental authority; after its approval file with the municipal or county agriculture authority and operate as registered","File with the agriculture authority; after filing obtain central competent authority approval and publication before operating as registered","Apply to the water resources authority; after its approval file with the municipal or county environmental authority and operate as approved"],
 "Article 70-1 paragraph 1."),

(W,"第70條之1",3,"水措-厭氧發酵",
 "沼液沼渣作為農地肥分，其厭氧發酵天數、施灌滲入時間及應變緩衝容量規定為何？",
 ["非草食性動物畜牧業十天以上、草食性動物五天以上；施灌後一小時內完全滲入土壤；應變緩衝容量應達十天以上","非草食性動物畜牧業五天以上、草食性動物十天以上；施灌後一小時內完全滲入土壤；應變緩衝容量應達十天以上","非草食性動物畜牧業十天以上、草食性動物五天以上；施灌後二十四小時內滲入土壤；應變緩衝容量應達三天以上","非草食性動物畜牧業三十天以上、草食性動物十五天以上；施灌後一小時內完全滲入土壤；應變緩衝容量應達一天以上"],"a",
 "第70條之1第1項第1款：畜牧糞尿排入厭氧發酵設施應能妥善收集沼氣，厭氧發酵天數為非草食性動物之畜牧業十天以上、草食性動物之畜牧業五天以上，但農業主管機關另為核定者依其核定。第3款：沼液沼渣應於施灌後一小時內完全滲入土壤，農地表面不得積留沼液，但以灌溉水混合溝灌或漫灌者不在此限。第4款：應備有暫停施灌期間之應變緩衝容量十天以上。",
 "What digestion days, infiltration time and buffer capacity are required?",
 ["Non-herbivore farms at least 10 days, herbivore farms at least 5 days; full infiltration within 1 hour; buffer capacity at least 10 days","Non-herbivore farms at least 5 days, herbivore farms at least 10 days; full infiltration within 1 hour; buffer capacity at least 10 days","Non-herbivore farms at least 10 days, herbivore farms at least 5 days; infiltration within 24 hours; buffer capacity at least 3 days","Non-herbivore farms at least 30 days, herbivore farms at least 15 days; full infiltration within 1 hour; buffer capacity at least 1 day"],
 "Article 70-1 paragraph 1 subparagraphs 1, 3 and 4."),

(W,"第70條之2",3,"水措-檢具文件",
 "沼液沼渣農地肥分使用計畫應檢具之沼液沼渣檢測報告，及施灌農地土壤品質背景值檢測報告，應包含哪些項目？",
 ["沼液沼渣應含氫離子濃度指數、導電度、總氮、總磷、銅、鋅；土壤品質應含土壤飽和萃取液導電度、銅、鋅等項目及土壤質地","沼液沼渣應含氫離子濃度指數、濁度、大腸桿菌群、化學需氧量；土壤品質應含土壤飽和萃取液導電度、鉛、鎘等項目及含水量","沼液沼渣應含氫離子濃度指數、導電度、總氮、總磷、汞、砷；土壤品質應含土壤飽和萃取液酸鹼值、汞、砷等項目及土壤質地","沼液沼渣應含水溫、懸浮固體、生化需氧量、油脂；土壤品質應含土壤飽和萃取液導電度、銅、鋅等項目及土壤有機質含量"],"a",
 "第70條之2第1項第2款：沼液、沼渣檢測報告應包含氫離子濃度指數、導電度、總氮、總磷、銅、鋅等項目。第6款：施灌農地土壤品質背景值檢測報告應包含土壤飽和萃取液導電度、銅、鋅等項目及土壤質地，並以地圖標示採樣地點。第5款：地下水水質背景值檢測報告應包含導電度、銨態氮或氨氮等項目及地下水井座標資料。",
 "Which parameters must the slurry and the soil background reports cover?",
 ["Slurry: pH, conductivity, total nitrogen, total phosphorus, copper, zinc; soil: saturation extract conductivity, copper, zinc, texture","Slurry: pH, turbidity, coliform bacteria, chemical oxygen demand; soil: saturation extract conductivity, lead, cadmium, moisture content","Slurry: pH, conductivity, total nitrogen, total phosphorus, mercury, arsenic; soil: saturation extract pH, mercury, arsenic, soil texture","Slurry: temperature, suspended solids, biochemical oxygen demand, grease; soil: saturation extract conductivity, copper, zinc, organic matter"],
 "Article 70-2 paragraph 1 subparagraphs 2, 5 and 6."),

(W,"第70條之2",3,"水措-監測備查",
 "沼液沼渣農地肥分使用者之地下水水質及土壤品質檢測報告，應於何時送備查？保存多久？監測頻率依何規定？",
 ["應於檢測報告完成後一個月內送農業主管機關及當地環保主管機關備查，並保存五年；監測頻率依附表四辦理","應於檢測報告完成後六個月內送農業主管機關及當地環保主管機關備查，並保存三年；監測頻率依附表一辦理","應於檢測報告完成後一個月內送中央主管機關及目的事業主管機關核准，並保存五年；監測頻率依附表二辦理","應於檢測報告完成後一年內送農業主管機關及當地環保主管機關備查，並保存十年；監測頻率由業者自行訂定"],"a",
 "第70條之2第3項：沼液沼渣農地肥分使用者應於地下水水質及土壤品質檢測報告完成後一個月內，送農業主管機關及當地環保主管機關備查，並保存五年。第1項第9款：承諾監測地下水水質及土壤品質，監測項目除土壤質地外其餘同背景值檢測報告項目，監測頻率依附表四辦理。",
 "When must groundwater and soil reports be filed, kept how long, at what frequency?",
 ["Within one month of completion to the agriculture and local environmental authorities, kept five years; frequency per Table 4","Within six months of completion to the agriculture and local environmental authorities, kept three years; frequency per Table 1","Within one month of completion to the central and industry competent authorities for approval, kept five years; frequency per Table 2","Within one year of completion to the agriculture and local environmental authorities, kept ten years; frequency set by the operator"],
 "Article 70-2 paragraphs 1 and 3."),

(W,"第70條之3",3,"水措-展延",
 "沼液沼渣農地肥分使用計畫之有效期限為何？應於何時申請展延？每次展延期限為何？",
 ["有效期限五年；應自期滿六個月前起算三個月之期間內向農業主管機關申請展延；每次展延不得超過五年","有效期限三年；應自期滿六個月前起算三個月之期間內向農業主管機關申請展延；每次展延不得超過三年","有效期限五年；應自期滿三個月前起算六個月之期間內向環保主管機關申請展延；每次展延不得超過十年","有效期限五年；應自期滿後三十日內向農業主管機關補行申請展延；每次展延不得超過二年之期間限制"],"a",
 "第70條之3第1項：沼液沼渣農地肥分使用計畫有效期限五年，期滿仍繼續使用者，應自期滿六個月前起算三個月之期間內向農業主管機關申請展延，每次展延不得超過五年。第2項：申請展延應檢具第70條之2第1項第5款、第6款以外規定之文件，但有效期間未有情節重大違規者，得逕出具切結書聲明與原審查同意文件相符申請展延。",
 "How long is the plan valid, when is renewal applied for, and for how long?",
 ["Valid five years; apply during the three-month window starting six months before expiry; each renewal is capped at five years","Valid three years; apply during the three-month window starting six months before expiry; each renewal is capped at three years","Valid five years; apply during the six-month window starting three months before expiry to the environmental authority; capped at ten years","Valid five years; apply retroactively within thirty days after expiry to the agriculture authority; each renewal is capped at two years"],
 "Article 70-3 paragraphs 1 and 2."),

(W,"第70條之4",2,"水措-審查文件",
 "沼液沼渣農地肥分使用計畫之審查同意文件應記載哪些事項？",
 ["使用者及施灌者名稱地址負責人、農地地號面積與施灌數量品質方式頻率用途、核發日期及計畫有效期限、其他必要記載事項","使用者及施灌者之營業額與員工人數、農地地號面積與施灌數量品質方式頻率用途、核發日期及計畫有效期限、其他必要事項","使用者及施灌者名稱地址負責人、農地公告現值與市價、核發日期及計畫有效期限、環境影響評估審查結論等必要記載事項","使用者及施灌者名稱地址負責人、農地地號面積與施灌數量品質方式頻率用途、核發日期但無須記載有效期限、其他必要事項"],"a",
 "第70條之4：審查同意文件應記載沼液沼渣農地肥分使用者及施灌者名稱、地址、負責人；施灌作業有關之農地地號、面積、沼液沼渣施灌數量、沼液沼渣品質、方式、頻率及用途；核發日期及計畫有效期限；其他必要記載事項。第70條之5第2項並就前開記載事項之變更訂有不同之辦理期限。",
 "What must the approval document for a land application plan state?",
 ["User and applicator names, addresses and heads; plot numbers, area, quantity, quality, method, frequency and use; issue date and validity; other items","User and applicator turnover and headcount; plot numbers, area, quantity, quality, method, frequency and use; issue date and validity; other items","User and applicator names, addresses and heads; land announced and market values; issue date and validity; the EIA review conclusion and other items","User and applicator names, addresses and heads; plot numbers, area, quantity, quality, method, frequency and use; issue date but no validity; other items"],
 "Article 70-4."),

(W,"第70條之5",3,"水措-計畫變更",
 "沼液沼渣農地肥分使用計畫變更或終止施灌農地共同執行合約時，應於何時辦理？",
 ["應於變更或終止之次日起三十日內，檢具變更後之合約書或終止合約文件影本送農業主管機關備查","應於變更或終止之次日起三日內，檢具變更後之合約書或終止合約文件影本送農業主管機關核准","應於變更或終止前三十日，檢具變更後之合約書或終止合約文件影本送環保主管機關核准後辦理","應於變更或終止之次日起一年內，檢具變更後之合約書或終止合約文件影本送中央主管機關備查"],"a",
 "第70條之5第2項第1款：變更或終止第70條之2第1項第3款施灌農地共同執行沼液沼渣農地肥分使用計畫之合約或同意書，應於變更或終止之次日起三十日內，檢具變更後之合約書或終止合約文件影本送農業主管機關備查。第2款：變更使用者及施灌者名稱地址負責人，或因地籍測量完成土地標示變更登記者，應自事實發生之次日起三十日內申請變更。",
 "When must a change or termination of the farmland cooperation contract be filed?",
 ["Within 30 days after the change or termination, file the revised or termination contract copy with the agriculture authority","Within 3 days after the change or termination, file the revised or termination contract copy with the agriculture authority for approval","30 days before the change or termination, file the revised or termination contract copy with the environmental authority for approval","Within one year after the change or termination, file the revised or termination contract copy with the central competent authority"],
 "Article 70-5 paragraph 2 subparagraph 1."),

(W,"第70條之6",3,"水措-暫停施灌",
 "經審查同意之沼液沼渣農地肥分使用者，於哪些情形應暫停沼液沼渣作為農地肥分？",
 ["自中央氣象署發布大雨、豪雨特報日起至解除日後三日之期間；地下水水質各項污染物指標明顯上升或土壤品質達土壤污染監測標準限值","自中央氣象署發布陸上颱風警報日起至解除當日之期間；地下水水質各項污染物指標明顯上升或土壤品質達土壤污染管制標準限值","自中央氣象署發布大雨、豪雨特報日起至解除日後三十日之期間；地下水水質各項污染物指標明顯下降或土壤品質達整治標準限值","自農作物採收日起至次期作物播種日後三日之期間；地下水水質各項污染物指標明顯上升或土壤品質達土壤污染監測標準之限值"],"a",
 "第70條之6第1項：自中央氣象署發布大雨、豪雨特報日起至解除日後三日之期間，及沼液沼渣作為農地肥分使用期間地下水水質監測結果各項污染物指標有明顯上升趨勢或土壤品質檢測結果達土壤污染監測標準之限值者，應暫停沼液沼渣作為農地肥分。第2項：暫停期間之因應措施應納入使用計畫併同審查。第49條之10對小型畜牧業亦準用本項情形。",
 "When must biogas slurry land application be suspended?",
 ["From a heavy rain advisory until three days after it is lifted; groundwater indicators clearly rising or soil reaching monitoring standard limits","From a land typhoon warning until the day it is lifted; groundwater indicators clearly rising or soil reaching pollution control standard limits","From a heavy rain advisory until thirty days after it is lifted; groundwater indicators clearly falling or soil reaching remediation standard limits","From crop harvest until three days after the next sowing; groundwater indicators clearly rising or soil reaching monitoring standard limits"],
 "Article 70-6."),

(W,"第70條之7",1,"水措-查獲通知",
 "直轄市、縣（市）環保主管機關查獲未依審查同意之沼液沼渣農地肥分使用計畫內容執行者，應如何處理？",
 ["應通知農業主管機關，要求業者改善","應逕行廢止其沼液沼渣使用計畫文件","應逕行裁處停工並註銷畜牧場登記證","應通知水利主管機關，要求停止取水"],"a",
 "第70條之7：直轄市、縣（市）環保主管機關查獲未依農業主管機關審查同意之沼液沼渣農地肥分使用計畫內容執行者，應通知農業主管機關，要求業者改善。第70條之8則規定農業主管機關得廢止使用計畫之違法情形，並應將辦理情形副知環保主管機關。",
 "What must the environmental authority do on finding non-compliant land application?",
 ["Notify the agriculture authority and require the operator to make improvements","Revoke the biogas slurry land application plan document on its own authority","Impose a shutdown penalty and cancel the livestock farm registration certificate","Notify the water resources authority and require water abstraction to cease"],
 "Article 70-7."),

(W,"第70條之8",3,"水措-廢止計畫",
 "農業主管機關得廢止沼液沼渣農地肥分使用計畫之違法情形為何？何時應廢止？",
 ["申請資料與事實不符、未依核定計畫進行農地肥分使用、有效期間內未依規定辦理變更經通知屆期未改善、其他違法情形；經認定情節重大者應廢止","申請資料與事實不符、未依核定計畫進行農地肥分使用、有效期間內未依規定辦理變更經通知屆期未改善、其他違法情形；經業者自行申請者應廢止","申請資料填載有誤字、未於期限內繳納規費、有效期間內未參加農業主管機關教育訓練、其他行政疏失；經認定情節重大者即應予以廢止","申請資料與事實不符、未依核定計畫進行農地肥分使用、有效期間內未依規定辦理變更經通知屆期未改善、其他違法情形；情節重大者僅得限期改善"],"a",
 "第70條之8第1項：申請資料內容與事實不符、未依核定計畫書內容進行農地肥分使用、有效期間內未依第70條之5第2項規定辦理變更經通知限期改善或補正屆期仍未改善補正、其他違法情形者，農業主管機關得廢止其使用計畫。第2項：前項各款違法情形經農業主管機關或環保主管機關認定情節重大者，農業主管機關應廢止其使用計畫。第3項：應將辦理情形副知環保主管機關。",
 "On what grounds may the plan be revoked, and when must it be revoked?",
 ["Data inconsistent with fact, use not per the approved plan, amendment not filed after notice, other violations; revocation is mandatory if serious","Data inconsistent with fact, use not per the approved plan, amendment not filed after notice, other violations; revocation is mandatory on request","Typographical errors, unpaid fees, training not attended during validity, other administrative lapses; revocation is mandatory if serious","Data inconsistent with fact, use not per the approved plan, amendment not filed after notice, other violations; serious cases only get a deadline"],
 "Article 70-8."),

(W,"第70條之9",3,"水措-處分依據",
 "有哪些情形者，以違反本辦法依本法規定處分？",
 ["違反第七十條之一第一項及第七十條之五未依審查同意之計畫登記事項運作者，及違反第七十條之六未暫停沼液沼渣作為農地肥分者","違反第七十條之一第一項及第七十條之五未依審查同意之計畫登記事項運作者，及未於期限內繳納農業主管機關所收取之規費者","僅有未取得沼液沼渣農地肥分使用計畫審查同意而逕行使用者，其餘依計畫運作之情形均不生違反本辦法而受處分之問題","違反第七十條之三未於期限內申請展延者，及違反第七十條之四未於審查同意文件記載核發日期與計畫有效期限之情形"],"a",
 "第70條之9第1項：違反第70條之1第1項及第70條之5未依農業主管機關審查同意之沼液沼渣農地肥分使用計畫登記事項運作，或違反第70條之6未暫停沼液、沼渣作為農地肥分者，以違反本辦法依本法規定處分。第2項：施灌過程所衍生之環境污染情事，依相關環保法規處分。",
 "Which situations are penalised as violations of this regulation under the Act?",
 ["Operating outside the approved plan's registered items under Articles 70-1(1) and 70-5, and failing to suspend application under Article 70-6","Operating outside the approved plan's registered items under Articles 70-1(1) and 70-5, and failing to pay the agriculture authority's fees on time","Only using slurry as fertiliser without an approved plan; any operation carried out under an approved plan can never breach this regulation","Failing to apply for renewal in time under Article 70-3, and omitting the issue date and validity period from the approval document"],
 "Article 70-9 paragraph 1."),

(W,"第70條之9",2,"水措-未經同意",
 "未取得沼液沼渣農地肥分使用計畫審查同意，逕將畜牧糞尿或沼液沼渣作為農地肥分使用者，應如何處分？",
 ["依違反本法規定處分；畜牧糞尿非全量作為農地肥分而排放於地面水體者，其排放應依本法規定辦理","依違反廢棄物清理法規定處分；畜牧糞尿非全量作為農地肥分而排放於地面水體者，得免依本法辦理","僅得由農業主管機關要求限期補辦審查同意程序，於補辦完成前不生依本法規定處分之效果與責任","依違反本法規定處分；畜牧糞尿非全量作為農地肥分而排放於地面水體者，得逕以稀釋方式處理排放"],"a",
 "第70條之9第3項：未取得沼液沼渣農地肥分使用計畫審查同意，逕將畜牧糞尿或沼液、沼渣作為農地肥分使用者，依違反本法規定處分。第4項：畜牧糞尿非全量作為農地肥分而有排放於地面水體者，或不符合本章規定而排放於土壤或地面水體者，其排放地面水體或土壤應依本法規定辦理。",
 "How is unapproved land application of manure or slurry penalised?",
 ["Penalised as a violation of the Act; partial application with surface water discharge must also comply with the Act","Penalised as a violation of the Waste Disposal Act; partial application with surface water discharge is exempt from the Act","The agriculture authority may only set a deadline to complete approval, with no liability under the Act until then","Penalised as a violation of the Act; partial application with surface water discharge may simply be diluted before release"],
 "Article 70-9 paragraphs 3 and 4."),

(W,"第70條之10",2,"水措-資訊通報",
 "農業主管機關核發畜牧糞尿水施灌農作個案再利用許可或沼液沼渣農地肥分使用計畫時，應如何辦理？",
 ["應一併將申請、變更及展延之核准資料通知各級主管機關，並將執行之監測及檢測情形錄案管理提供環保主管機關","應一併將申請、變更及展延之核准資料公告於指定網站，並將執行之監測及檢測情形函送目的事業主管機關備查","應一併將申請、變更及展延之核准資料通知各級主管機關，惟執行之監測及檢測情形屬機密不得提供環保主管機關","應一併將申請、變更及展延之核准資料通知施灌農地所有權人，並將執行之監測及檢測情形提供當地農會查閱"],"a",
 "第70條之10第1項：農業主管機關核發畜牧糞尿水施灌農作個案再利用許可，或依本辦法核發沼液沼渣農地肥分使用計畫時，應一併將申請、變更及展延之核准資料，通知各級主管機關。第2項：使用者自核准日起依核准計畫或許可內容施灌。第3項：農業主管機關應將執行之監測及檢測等情形錄案管理，並將資訊提供直轄市、縣（市）環保主管機關。",
 "What must the agriculture authority do when issuing such permits or plans?",
 ["Notify all levels of competent authority of application, amendment and renewal approvals, and share monitoring records with the environmental authority","Publish application, amendment and renewal approvals on the designated website, and send monitoring records to the industry authority for record","Notify all levels of competent authority of application, amendment and renewal approvals, but withhold monitoring records as confidential","Notify the owners of the irrigated farmland of the approvals, and make the monitoring records available to the local farmers association"],
 "Article 70-10."),

(W,"第71條",3,"水措-免申報",
 "下列哪些事業或污水下水道系統免依本辦法規定辦理檢測申報？",
 ["未附設洗車場之加油站、營建工地、飼養豬未滿二百頭之畜牧業、貯存系統、廢水納入公共污水下水道系統者、洗腎診所等","附設洗車場之加油站、營建工地、飼養豬二千頭以上之畜牧業、貯存系統、廢水納入工業區污水下水道系統者、醫學中心等","未附設洗車場之加油站、科學園區廠商、飼養豬未滿二百頭之畜牧業、發電廠、廢水以海放管排放於海洋者、觀光旅館等","未附設洗車場之加油站、營建工地、飼養牛未滿二百頭之畜牧業、貯存系統、廢水排放於地面水體者、餐飲業與旅館業等"],"a",
 "第71條第1項：未附設洗車場之加油站、營建工地、飼養豬未滿二百頭之畜牧業、貯存系統、廢（污）水納入公共污水下水道系統者、洗腎診所、水庫總磷削減總量管制區之事業且非屬本法公告之其他事業，以及取得全量資源化證明或全量委託證明經核准之畜牧業等，免依本辦法規定辦理檢測申報。",
 "Which entities are exempt from testing and reporting under this regulation?",
 ["Filling stations without car washes, construction sites, farms under 200 pigs, storage systems, users of public sewers, dialysis clinics","Filling stations with car washes, construction sites, farms over 2,000 pigs, storage systems, users of industrial park sewers, medical centres","Filling stations without car washes, science park firms, farms under 200 pigs, power plants, sea outfall dischargers, tourist hotels","Filling stations without car washes, construction sites, farms under 200 cattle, storage systems, surface water dischargers, restaurants"],
 "Article 71 paragraph 1."),

(W,"第71條",2,"水措-納管申報",
 "事業廢水納入公共污水下水道系統以外之污水下水道系統者，其申報程序為何？",
 ["應先向污水下水道系統管理機關（構）申報，再由該管理機關（構）彙整後向直轄市、縣（市）主管機關申報","應直接向直轄市、縣（市）主管機關申報，無須先向污水下水道系統管理機關（構）申報亦無須彙整","應先向中央主管機關申報，再由中央主管機關彙整後轉知污水下水道系統管理機關（構）備查存查","應先向目的事業主管機關申報，再由該機關彙整後向污水下水道系統管理機關（構）申報並備查"],"a",
 "第71條第2項：事業或污水下水道系統廢（污）水納入第1項第5款（公共污水下水道系統）以外之污水下水道系統者，應先向污水下水道系統管理機關（構）申報，再由污水下水道系統管理機關（構）彙整後，向直轄市、縣（市）主管機關申報。第76條並定有納入工業區專用污水下水道系統之申報內容。",
 "How do users of non-public sewerage systems report?",
 ["Report first to the sewerage system authority, which consolidates and reports to the municipal or county competent authority","Report directly to the municipal or county competent authority, with no prior reporting or consolidation by the sewerage authority","Report first to the central competent authority, which consolidates and informs the sewerage system authority for its records","Report first to the industry competent authority, which consolidates and reports to the sewerage system authority for record"],
 "Article 71 paragraph 2."),

(W,"第72條",2,"水措-貯留申報",
 "事業採貯留廢水者，其申報內容包括哪些項目？",
 ["製程設施及生產規模、原廢水水質與檢測當日水量及每月來源產生量貯留量、貯留設施放置地點數量、貯留後之後續處理行為等","製程設施及生產規模、原廢水水質與檢測當日水量及每月來源產生量貯留量、貯留設施之購置金額與折舊年限、保險理賠情形等","僅需申報貯留設施之放置地點及數量即可，無須申報原廢水水質與檢測當日水量、每月來源產生量及後續處理行為等事項","製程設施及生產規模、放流水水質與檢測當日水量及每月排放量、貯留設施操作人員名冊、貯留後之後續處理行為之說明"],"a",
 "第72條第1項：採貯留廢（污）水者應申報每月與廢水污泥產生量有關之製程設施及生產或服務規模、原廢水水質與檢測當日之水量及每月廢水來源產生量及貯留量、貯留設施之放置地點及數量、貯留後之後續處理行為（依採行各水措規定之內容申報）、貯留設施之自動液位計測設施或計量方式之校正維護日期及方法。第2項：廢棄物掩埋場返送滲出水者應申報每月返送至掩埋面之廢水量。",
 "What must an enterprise storing wastewater report?",
 ["Process facilities and scale; raw wastewater quality, test day flow, monthly source, generation and storage; storage locations and numbers; subsequent handling","Process facilities and scale; raw wastewater quality, test day flow, monthly source, generation and storage; purchase cost and depreciation; insurance claims","Only the location and number of storage facilities, without reporting raw wastewater quality, test day flow, monthly generation or subsequent handling","Process facilities and scale; effluent quality, test day flow and monthly discharge; a roster of storage facility operators; subsequent handling described"],
 "Article 72."),

(W,"第73條",3,"水措-處理申報",
 "事業採廢（污）水（前）處理設施處理廢水者，其申報內容包括哪些？",
 ["原廢水與處理後水質及檢測當日水量、每月用水量與廢水產生量及處理水量、每月使用藥劑名稱與使用量、電度表維護更換日期與每月用電量等","原廢水與處理後水質及檢測當日水量、每月用水量與廢水產生量及處理水量、每月員工人數與加班時數、電度表之購置廠牌與型號及保固期限等","僅需申報原廢水與處理後之水質及檢測當日水量即可，無須申報每月用水量、廢水產生量、藥劑使用量及處理設施之用電量等事項","放流水水質與檢測當日水量、每年用水量與廢水產生量及處理水量、每年使用藥劑名稱與使用量、電度表維護更換日期與每年用電量等"],"a",
 "第73條：申報內容包括每月與廢水污泥產生量有關之製程設施及生產或服務規模、原廢水與（前）處理後之水質及檢測當日之水量、每月用水來源用水量廢水產生量及處理水量（並依各股不同製程或來源分別申報）、處理設施操作方式及每月操作維護費用、每月使用藥劑名稱及使用量、主要處理單元正常操作參數之最大最小平均值、電度表之維護更換日期及每月用電量、每月污泥產生量含水率及操作頻率等。",
 "What must an enterprise operating treatment facilities report?",
 ["Raw and treated water quality with test day flow; monthly water use, generation and treated volume; chemical names and amounts; meter maintenance and monthly power use","Raw and treated water quality with test day flow; monthly water use, generation and treated volume; monthly headcount and overtime; meter brand, model and warranty","Only raw and treated water quality with test day flow, without reporting monthly water use, wastewater generation, chemical use or facility power consumption","Effluent quality with test day flow; annual water use, generation and treated volume; annual chemical names and amounts; meter maintenance and annual power use"],
 "Article 73."),

(W,"第74條",3,"水措-受託稀釋申報",
 "採處理設施且以餘裕量受託處理、採稀釋或委託代操作者，除依第七十三條申報外，還應申報哪些內容？",
 ["受託者應申報每月自行產生水量及餘裕量與收受來源業別及累積受託水量；稀釋者應申報稀釋用水水質水量來源及稀釋管線口之數量位置","受託者應申報每月自行產生水量及餘裕量與收受來源業別及累積受託水量；稀釋者應申報稀釋用水之採購價格及供應商名稱與契約期限","受託者應申報委託契約之金額與付款方式及違約條款；稀釋者應申報稀釋用水水質水量來源及稀釋管線稀釋口之數量與設置位置","受託者應申報每月自行產生水量及餘裕量與收受來源業別及累積受託水量；稀釋者僅需申報稀釋之總水量，其餘項目均得免予申報"],"a",
 "第74條：以餘裕量受託處理者應申報每月處理自行產生之廢水量及其餘裕量、每月收受廢水來源之業別及已累積受託處理之廢水量；採稀釋廢水者應申報稀釋用水之水質及檢測當日之水量、每月稀釋用水之來源與水量、稀釋管線及稀釋口之數量與位置；委託代操作者應申報代操作者之名稱、代操作人員姓名及異動情形。",
 "What additional items must entrusted treatment, dilution or contract operation report?",
 ["Providers report monthly own generation, spare capacity, source sectors and cumulative volume; dilution reports water quality, flow, source, pipe and port counts","Providers report monthly own generation, spare capacity, source sectors and cumulative volume; dilution reports purchase price, supplier names and contract term","Providers report contract value, payment terms and penalty clauses; dilution reports water quality, flow, source, and dilution pipe and port counts and locations","Providers report monthly own generation, spare capacity, source sectors and cumulative volume; dilution reports only total volume, with all other items waived"],
 "Article 74."),

(W,"第75條",3,"水措-額外申報",
 "採處理設施之事業於哪些情形應另行申報特定事項？",
 ["應收集處理逕流廢水者申報每月收集處理水量；第九條事業申報洗車台水量與沉砂池液面高度；泡湯餐飲業申報過濾及油脂截留設施維護日期","應收集處理逕流廢水者申報每月降雨日數；第九條事業申報工地施工進度與完工日期；泡湯餐飲業申報每月營業額與來客數及消費金額","應收集處理逕流廢水者申報每月收集處理水量；第九條事業申報洗車台水量與沉砂池液面高度；泡湯餐飲業申報泉源溫度與泉質分析報告","應收集處理逕流廢水者申報每月收集處理水量；第九條事業申報員工宿舍人數；泡湯餐飲業申報過濾設施之採購金額與供應廠商名稱等"],"a",
 "第75條：依第8條或第11條第2項應收集處理逕流廢水者應申報每月收集處理之逕流廢水水量；第9條之事業應申報每月收集洗車台廢水進入沉砂池處理之水量、每月沉砂池最高液面距池頂之高度及量測方法、擋雨遮雨導雨設施及沉砂池之維護狀況與收集初期降雨量之水量；餐飲業觀光旅館提供泡湯服務者應申報毛髮及懸浮固體過濾設施維護日期方法，提供餐飲服務者應申報油脂截留設施維護日期方法；第49條之2事業應申報營建剩餘土石方相關數量。",
 "Which extra items must certain enterprises report?",
 ["Runoff collectors report monthly volume; Article 9 firms report car wash flow and basin freeboard; spa and food firms report filter and interceptor maintenance","Runoff collectors report monthly rainy days; Article 9 firms report construction progress and completion date; spa and food firms report turnover and customers","Runoff collectors report monthly volume; Article 9 firms report car wash flow and basin freeboard; spa and food firms report spring temperature and quality analysis","Runoff collectors report monthly volume; Article 9 firms report dormitory headcount; spa and food firms report filter purchase cost and the supplier's company name"],
 "Article 75 paragraph 1."),

(W,"第76條",2,"水措-工業區納管",
 "事業廢水納入工業區專用污水下水道系統者，其申報內容為何？",
 ["製程設施及生產規模、排入下水道系統之水質與檢測當日水量及每月用水量與排入水量、設有前處理設施者另依第七十三條至第七十五條申報","製程設施及生產規模、排入下水道系統之水質與檢測當日水量及每月用水量與排入水量、下水道系統管理機關之收費費率及繳費證明文件","製程設施及生產規模、放流口座標及採樣平台面積與告示牌規格尺寸、設有前處理設施者另依第七十三條至第七十五條規定之內容申報","製程設施及生產規模、排入下水道系統之水質與檢測當日水量及每年用水量與排入水量、設有前處理設施者得免依其他條文規定另行申報"],"a",
 "第76條：事業廢（污）水納入工業區專用污水下水道系統者，申報內容為每月與廢水污泥產生量有關之製程設施及生產或服務規模、排入污水下水道系統之水質與檢測當日之水量及每月用水來源用水量及排入污水下水道系統之水量、設置廢（污）水前處理設施者應另依第73條至第75條規定之內容申報。",
 "What must an enterprise connected to an industrial park sewer report?",
 ["Process facilities and scale; sewer inflow quality, test day flow, monthly water use and discharged volume; pre-treatment users also report per Articles 73 to 75","Process facilities and scale; sewer inflow quality, test day flow, monthly water use and discharged volume; the sewer authority's tariff and payment receipts","Process facilities and scale; outfall coordinates, sampling platform area and signboard dimensions; pre-treatment users also report per Articles 73 to 75","Process facilities and scale; sewer inflow quality, test day flow, annual water use and discharged volume; pre-treatment users are exempt from other articles"],
 "Article 76."),

(W,"第77條",3,"水措-委託申報",
 "事業採委託處理廢水者，其申報內容包括哪些？",
 ["製程設施及生產規模、原廢水水質與檢測當日水量及每月用水量與廢水產生量、委託處理之頻率水質水量、受託者名稱及業別等","製程設施及生產規模、原廢水水質與檢測當日水量及每月用水量與廢水產生量、委託契約之議價過程、受託者之資本額及員工人數等","製程設施及生產規模、放流水水質與檢測當日水量及每月排放量與污泥量、委託處理之頻率水質水量、受託者負責人之身分證影本等","僅需申報受託者之名稱及業別即可，無須申報原廢水水質與檢測當日水量、每月用水量、廢水產生量及委託處理之頻率與水量等"],"a",
 "第77條：採委託處理廢（污）水者，申報內容為每月與廢水污泥產生量有關之製程設施及生產或服務規模、原廢水水質與檢測當日之水量及每月用水來源用水量及廢水產生量、委託處理之頻率水質與檢測當日之水量及每月委託處理之水量、受託者名稱及業別、出流水端之水量計測設施或計量方式之校正維護日期與方法及每月讀數、作業環境內設置之貯留設施依第72條規定申報。",
 "What must an enterprise entrusting wastewater treatment report?",
 ["Process facilities and scale; raw water quality, test day flow, monthly water use and generation; entrustment frequency, quality and volume; provider name and sector","Process facilities and scale; raw water quality, test day flow, monthly water use and generation; contract negotiation history; provider capital and headcount","Process facilities and scale; effluent quality, test day flow, monthly discharge and sludge; entrustment frequency, quality and volume; the provider head's ID copy","Only the provider's name and sector, without reporting raw water quality, test day flow, monthly water use, generation, or entrustment frequency and volume"],
 "Article 77."),

(W,"第78條",2,"水措-海放申報",
 "以海放管排放廢水於海洋者，其申報內容包括哪些？",
 ["製程設施及生產規模、海放管管線修護方式及頻率、海域環境監測之採樣位置頻率監測項目及結果、設有處理設施者另依規定申報","製程設施及生產規模、海放管管線之造價及使用年限、海域環境監測之採樣位置頻率監測項目及結果、設有處理設施者另依規定申報","製程設施及生產規模、海放管管線修護方式及頻率、船舶航行安全通報紀錄與海事保險資料、設有處理設施者得免另依規定申報","放流口座標及告示牌規格、海放管管線修護方式及頻率、海域環境監測之採樣位置頻率監測項目及結果、設有處理設施者另申報"],"a",
 "第78條：以海放管排放廢（污）水於海洋者，申報內容為每月與廢水污泥產生量有關之製程設施及生產或服務規模、海放管管線修護方式及頻率、海域環境監測之採樣位置頻率監測項目及監測結果、設置廢（污）水（前）處理設施者應另依第73條至第75條規定之內容申報。第86條並規定海放管排放者申報頻率為每三個月一次。",
 "What must a sea outfall discharger report?",
 ["Process facilities and scale; outfall repair methods and frequency; marine monitoring locations, frequency, parameters and results; treatment users also report","Process facilities and scale; outfall construction cost and service life; marine monitoring locations, frequency, parameters and results; treatment users also report","Process facilities and scale; outfall repair methods and frequency; shipping safety notification logs and marine insurance data; treatment users are exempt","Outfall coordinates and signboard specifications; outfall repair methods and frequency; marine monitoring locations, frequency, parameters and results; plus reports"],
 "Article 78."),

(W,"第79條",3,"水措-回收申報",
 "畜牧業以外之事業採廢水回收使用者，其回收用水水質於何種情形得免檢測申報？",
 ["廢水回收作為製程之用，或回收作為洗滌塔或其他污染防治設備之用且回收使用後之水經設置之處理設施處理者","廢水回收作為員工宿舍沖廁之用，或回收作為景觀澆灌之用且回收使用後之水經設置之處理設施處理者之情形","廢水回收作為製程之用，或回收作為冷卻水塔補水之用且回收使用後之水未經設置之處理設施處理者之情形","一律不得免檢測申報回收用水之水質，均應按規定頻率檢測並申報回收用水之水質與檢測當日之水量數據"],"a",
 "第79條第1項第4款：應申報回收用水之水質與檢測當日之水量及每月回收使用之水量，但廢（污）水回收作為製程之用，或廢（污）水回收作為洗滌塔或其他污染防治設備之用且其回收使用後之水經設置之廢（污）水（前）處理設施處理者，免檢測申報回收用水之水質與檢測當日之水量。此與第41條第1項但書之免採樣口規定相呼應。",
 "When is recycled water quality exempt from testing and reporting?",
 ["Where recycled water is used in the process, or used in scrubbers or other control equipment with the returned water treated on site","Where recycled water is used for dormitory toilet flushing, or for landscape irrigation with the returned water treated on site","Where recycled water is used in the process, or used as cooling tower make-up with the returned water left untreated on site","No exemption exists at all; recycled water quality and test day flow must always be tested and reported at the set frequency"],
 "Article 79 paragraph 1 subparagraph 4."),

(W,"第79條",3,"水措-沉澱回收",
 "第九條之事業僅採沉澱處理後回收使用者，除依第一項申報外，還應申報哪些事項？",
 ["每月礦物砂石或預拌混凝土產量、每月用水量與沉砂池產生之污泥量、每月沉砂池處理水量及去除率、污泥之清除頻率及方式","每月礦物砂石或預拌混凝土售價、每月用水量與沉砂池產生之污泥量、每月沉砂池處理水量及去除率、污泥之清除承包商名稱","每月礦物砂石或預拌混凝土產量、每月用電量與員工出勤紀錄、每月沉砂池之施工進度、污泥之清除頻率方式及處理費用單據","每月礦物砂石或預拌混凝土產量、每月用水量與沉砂池產生之污泥量、每年沉砂池處理水量及去除率、污泥之清除頻率與方式"],"a",
 "第79條第3項：第9條之事業僅採沉澱處理後回收使用者，除依第1項規定申報外，並應申報每月礦物、砂、石或預拌混凝土之產量，每月用水量及沉砂池產生之污泥量，每月沉砂池處理之水量與去除率，以及沉砂池或污泥濃縮池污泥之清除頻率與方式。第2項並就畜牧業採回收使用者訂有較簡化之申報內容。",
 "What extra items must Article 9 firms recycling after sedimentation report?",
 ["Monthly mineral, sand, stone or concrete output; monthly water use and basin sludge; monthly basin treated volume and removal rate; sludge removal frequency and method","Monthly mineral, sand, stone or concrete prices; monthly water use and basin sludge; monthly basin treated volume and removal rate; sludge removal contractor name","Monthly mineral, sand, stone or concrete output; monthly power use and attendance records; monthly basin construction progress; sludge removal cost receipts","Monthly mineral, sand, stone or concrete output; monthly water use and basin sludge; annual basin treated volume and removal rate; sludge removal frequency and method"],
 "Article 79 paragraph 3."),

(W,"第80條",2,"水措-漁牧申報",
 "畜牧業採漁牧綜合經營者，其申報內容包括哪些？",
 ["魚池面積與實際飼養頭數、每月清洗畜舍頻率及水量、每月排放魚池廢水量與計量方式、每月魚池曝氣機用電量、魚池溶氧檢測值及日期","魚池面積與實際飼養頭數、每月清洗畜舍頻率及水量、每月魚貨銷售量與市場價格、每月魚池曝氣機採購金額、魚池水溫檢測值及日期","魚池面積與魚苗放養數量、每年清洗畜舍頻率及水量、每年排放魚池廢水量與計量方式、每年魚池曝氣機用電量、魚池濁度檢測值日期","魚池面積與實際飼養頭數、每月清洗畜舍頻率及水量、每月排放魚池廢水量與計量方式、每月飼料採購量、魚池氨氮檢測值及日期"],"a",
 "第80條：漁牧綜合經營者申報內容為魚池面積與實際飼養頭數、每月清洗畜舍之頻率及水量、每月排放魚池廢水量與計量方式、每月魚池曝氣機用電量、魚池溶氧檢測值及檢測日期、每月經漁牧綜合經營後之廢（污）水放流日期及處置方式。第46條並定有每公頃魚池廢水量四立方公尺以下及溶氧一．○毫克／公升以上等操作規定。",
 "What must an integrated fish and livestock operation report?",
 ["Pond area and actual head count; monthly barn washing frequency and volume; monthly pond discharge and metering; aerator power use; dissolved oxygen and test dates","Pond area and actual head count; monthly barn washing frequency and volume; monthly fish sales and market prices; aerator purchase cost; water temperature and dates","Pond area and fingerlings stocked; annual barn washing frequency and volume; annual pond discharge and metering; annual aerator power use; turbidity and test dates","Pond area and actual head count; monthly barn washing frequency and volume; monthly pond discharge and metering; monthly feed purchases; ammonia and test dates"],
 "Article 80."),

(W,"第81條",2,"水措-排放申報",
 "事業採廢水排放於地面水體者，其申報內容包括哪些？",
 ["製程設施及生產規模、排放廢水之水質與檢測當日水量及每月排放水量、放流水水量計測設施校正維護日期方法及每月讀數","製程設施及生產規模、排放廢水之水質與檢測當日水量及每月排放水量、承受水體之流量與水深及沿岸土地使用分區資料","製程設施及生產規模、原廢水之水質與檢測當日水量及每年排放水量、放流水水量計測設施之購置金額廠牌及保固期限等","放流口座標與告示牌規格、排放廢水之水質與檢測當日水量及每月排放水量、放流水水量計測設施操作人員之證照影本等"],"a",
 "第81條：採廢（污）水排放於地面水體者，申報內容為每月與廢水污泥產生量有關之製程設施及生產或服務規模、排放廢（污）水之水質與檢測當日之水量及每月排放水量、放流水水量計測設施或計量方式之校正維護日期與方法及每月讀數或量測值、設置廢（污）水（前）處理設施者應另依第73條至第75條規定之內容申報。",
 "What must a surface water discharger report?",
 ["Process facilities and scale; discharge quality, test day flow and monthly volume; effluent meter calibration dates, methods and monthly readings","Process facilities and scale; discharge quality, test day flow and monthly volume; receiving water flow, depth and riparian land use zoning data","Process facilities and scale; raw water quality, test day flow and annual volume; effluent meter purchase cost, brand and warranty period details","Outfall coordinates and signboard specifications; discharge quality, test day flow and monthly volume; copies of the meter operators' certificates"],
 "Article 81."),

(W,"第82條",2,"水措-土壤申報",
 "事業採土壤處理廢水者，除依第七十三條至第七十五條申報外，應另申報哪些事項？",
 ["每月作物種類、每公頃飼養頭數及土壤處理面積、排放於土壤之水質與檢測當日水量及每月排放水量、土壤及地下水監測資料等","每月作物種類、每公頃飼養頭數及土壤處理面積、排放於土壤之水質與檢測當日水量及每月排放水量、農地之公告現值及地價稅","每月農產品銷售量及售價、每公頃飼養頭數及土壤處理面積、排放於土壤之水質與檢測當日水量及每月排放量、氣象觀測資料等","每月作物種類、每公頃飼養頭數及土壤處理面積、排放於地面水體之水質與每月排放水量、土壤及地下水監測資料與監測井座標"],"a",
 "第82條：採土壤處理廢（污）水者，除應依第73條至第75條規定申報外，並應申報每月作物種類、每公頃飼養頭數及土壤處理面積，排放於土壤之水質與檢測當日之水量及每月排放土壤之水量，土壤及地下水監測資料，以及每月固液分離設施之操作頻率。第85條並就土壤處理之監測井及土壤採樣數量另有規定。",
 "What extra items must a soil treatment operator report?",
 ["Monthly crop types, head count per hectare and treated area; soil discharge quality, test day flow and monthly volume; soil and groundwater monitoring data","Monthly crop types, head count per hectare and treated area; soil discharge quality, test day flow and monthly volume; land announced value and land tax","Monthly farm produce sales and prices; head count per hectare and treated area; soil discharge quality, test day flow and monthly volume; weather observation data","Monthly crop types, head count per hectare and treated area; surface water discharge quality and monthly volume; soil and groundwater data and well coordinates"],
 "Article 82."),

(W,"第83條",3,"水措-操作條件",
 "事業執行定期檢測時之操作條件規定為何？",
 ["事業應符合許可證核准登記之每日最大廢水產生量之百分之六十以上；未達者應以當次定期檢測申報期間實際產生量之平均水量為準","事業應符合許可證核准登記之每日最大廢水產生量之百分之九十以上；未達者應以當次定期檢測申報期間實際產生量之最大水量為準","事業應符合許可證核准登記之每日最小廢水產生量之百分之六十以上；未達者應以前一年度定期檢測申報期間之平均水量為準辦理","事業應符合許可證核准登記之每日最大廢水產生量之百分之三十以上；未達者得逕以核准登記之每日最大廢水產生量為準辦理"],"a",
 "第83條第3項：事業應符合許可證（文件）核准登記之每日最大廢（污）水產生量之百分之六十以上，但定期檢測申報期間之操作條件未達百分之六十以上者，應以當次定期檢測申報期間實際廢水產生量之平均水量為準；污水下水道系統則以每日最大納管水量之百分之六十以上為準。第5項：經認定未能符合檢測操作條件者應重新檢測，但得提出書面文件仍屬正常操作者不在此限。",
 "What operating condition applies when conducting periodic testing?",
 ["At least 60 percent of the permitted maximum daily generation; if below, use the average actual flow during that reporting period","At least 90 percent of the permitted maximum daily generation; if below, use the maximum actual flow during that reporting period","At least 60 percent of the permitted minimum daily generation; if below, use the average flow of the previous year's reporting period","At least 30 percent of the permitted maximum daily generation; if below, simply use the permitted maximum daily generation figure"],
 "Article 83 paragraphs 3 and 5."),

(W,"第83條",2,"水措-檢測頻率",
 "事業申報之水質、水量、監測資料，其檢測、量測、監測頻率依何規定辦理？主管機關得否增加？",
 ["依附表一規定辦理；主管機關得視實際需要命增加全部或部分申報項目之頻率，必要時並得命依指定位置頻率項目檢測逕流廢水","依附表三規定辦理；主管機關得視實際需要命增加全部或部分申報項目之頻率，必要時並得命依指定位置頻率項目檢測逕流廢水","依事業自行訂定之標準作業程序辦理；主管機關不得命增加申報項目之檢測頻率，亦不得命檢測逕流廢水或監測承受水體","依附表一規定辦理；主管機關僅得命減少申報項目之檢測頻率，不得命增加，亦不得命依指定位置檢測逕流廢水或水體"],"a",
 "第83條第1項：事業或污水下水道系統申報之水質、水量、監測資料，其檢測、量測、監測頻率依附表一規定辦理。第2項：主管機關得視實際需要命增加全部或部分申報項目之檢測量測監測頻率，必要時並得命其依指定位置、頻率及項目，檢測申報逕流廢水或監測申報承受水體。第84條第1項並規定申報水質項目依附表一辦理，主管機關得依需要增加申報項目。",
 "Which schedule sets testing frequency, and may the authority increase it?",
 ["Table 1 sets the frequency; the authority may raise frequencies and order runoff testing at designated locations and parameters where needed","Table 3 sets the frequency; the authority may raise frequencies and order runoff testing at designated locations and parameters where needed","The enterprise's own standard operating procedure applies; the authority may not raise frequencies nor order runoff or receiving water testing","Table 1 sets the frequency; the authority may only lower frequencies, never raise them, nor order runoff or receiving water testing anywhere"],
 "Article 83 paragraphs 1 and 2."),

(W,"第84條",3,"水措-生物急毒性",
 "哪些事業之核准許可廢水排放量達每日多少立方公尺以上者，應檢測申報放流水之生物急毒性？",
 ["工業區專用污水下水道系統或晶圓半導體、光電材料、印刷電路板、石油化學、化工、造紙業，排放量達每日二萬立方公尺以上者","工業區專用污水下水道系統或晶圓半導體、光電材料、印刷電路板、石油化學、化工、造紙業，排放量達每日二千立方公尺以上者","公共污水下水道系統或食品製造、紡織染整、皮革、電鍍、金屬表面處理業，排放量達每日二萬立方公尺以上者應檢測申報之","工業區專用污水下水道系統或晶圓半導體、光電材料、印刷電路板、石油化學、化工、造紙業，排放量達每日二十萬立方公尺者"],"a",
 "第84條第3項：工業區專用污水下水道系統，或屬晶圓製造及半導體製造業、光電材料及元件製造業、印刷電路板製造業、石油化學業、化工業、造紙業之事業，核准許可廢（污）水排放量達每日二萬立方公尺以上者，應檢測申報放流水水質之生物急毒性；但原水來源為海水或放流水為高濃度鹵離子廢水且排入之承受水體為海洋者不在此限。第4項：排放量以作業廢水及洩放廢水計算。",
 "Which dischargers above what daily volume must test effluent acute toxicity?",
 ["Industrial park sewers, or semiconductor, optoelectronic, PCB, petrochemical, chemical and paper industries discharging 20,000 CMD or more","Industrial park sewers, or semiconductor, optoelectronic, PCB, petrochemical, chemical and paper industries discharging 2,000 CMD or more","Public sewerage systems, or food, textile dyeing, leather, electroplating and metal finishing industries discharging 20,000 CMD or more","Industrial park sewers, or semiconductor, optoelectronic, PCB, petrochemical, chemical and paper industries discharging 200,000 CMD"],
 "Article 84 paragraphs 3 and 4."),

(W,"第84條",2,"水措-免檢測申報",
 "事業之製程及處理程序中不使用且不產出附表一應申報之水質項目時，得如何辦理？",
 ["得檢具證明文件，向直轄市、縣（市）主管機關申請免檢測申報該項目；檢測結果低於方法偵測極限者亦同","得逕行自行決定免檢測申報該項目，無須檢具證明文件亦無須向直轄市、縣（市）主管機關提出申請核准","得檢具證明文件，向中央主管機關申請免檢測申報該項目並公告之；檢測結果低於方法偵測極限者則不得申請","得檢具證明文件，向目的事業主管機關申請免檢測申報該項目；惟檢測結果低於方法偵測極限者仍應照常申報"],"a",
 "第84條第2項：事業或污水下水道系統之製程及廢（污）水處理程序中不使用且不產出附表一應申報之水質項目，或附表一應申報之水質項目檢測結果低於方法偵測極限者，得檢具證明文件向直轄市、縣（市）主管機關申請免檢測申報該項目。第1項並規定主管機關得依實際需要增加申報項目。",
 "How may an enterprise be exempted from testing a Table 1 parameter?",
 ["Submit supporting documents to the municipal or county authority for exemption; the same applies below the method detection limit","Simply decide on its own to skip the parameter, with no supporting documents and no application to the municipal or county authority","Submit supporting documents to the central competent authority for exemption and publication; results below the detection limit cannot apply","Submit supporting documents to the industry competent authority for exemption; results below the detection limit must still be reported"],
 "Article 84 paragraph 2."),

(W,"第84條之1",3,"水措-急毒性檢測",
 "辦理放流水生物急毒性檢測時，應選定哪些生物？其基本檢測申報頻率為何？",
 ["應於鯉魚、羅漢魚、斑馬魚胚胎擇一，及水蚤、米蝦擇一，進行二種生物檢測；基本頻率為每六個月一次","應於鯉魚、羅漢魚、斑馬魚胚胎擇二，及水蚤、米蝦擇二，進行四種生物檢測；基本頻率為每六個月一次","應於吳郭魚、鰻魚、虱目魚苗擇一，及豐年蝦、螺類擇一，進行二種生物檢測；基本頻率為每三個月一次","應於鯉魚、羅漢魚、斑馬魚胚胎擇一，及水蚤、米蝦擇一，進行二種生物檢測；基本頻率為每年檢測一次"],"a",
 "第84條之1第1項：辦理放流水水質之生物急毒性檢測，應於鯉魚、羅漢魚、斑馬魚胚胎擇一選定及水蚤、米蝦擇一選定，進行二種生物檢測，並依中央主管機關公告之檢測方法執行，主管機關稽查採樣時亦同。第2項：依第84條第3項規定檢測申報者，其頻率為每六個月一次。第2條第14款並定義 TUa 為半數致死濃度之倒數。",
 "Which organisms are used for acute toxicity testing, and at what base frequency?",
 ["One of carp, topmouth gudgeon or zebrafish embryo plus one of water flea or freshwater shrimp, two species in all; base frequency every six months","Two of carp, topmouth gudgeon or zebrafish embryo plus two of water flea or freshwater shrimp, four species in all; base frequency every six months","One of tilapia, eel or milkfish fry plus one of brine shrimp or snail, two species in all; base frequency every three months instead","One of carp, topmouth gudgeon or zebrafish embryo plus one of water flea or freshwater shrimp, two species in all; base frequency once every year"],
 "Article 84-1 paragraphs 1 and 2."),

(W,"第84條之1",3,"水措-頻率調整",
 "放流水生物急毒性檢測申報頻率如何依 TUa 值調整？",
 ["任一次二種生物TUa值均超過一．四三時每三個月一次，連續三次以上均低於一．四三回復每六個月一次；連續六次以上均低於者得每年一次","任一次二種生物TUa值均超過一．四三時每個月一次，連續三次以上均低於一．四三回復每三個月一次；連續六次以上均低於者得每半年一次","任一次二種生物TUa值均超過十四．三時每三個月一次，連續三次以上均低於十四．三回復每六個月一次；連續六次以上均低於者得每年一次","任一次二種生物TUa值均低於一．四三時每三個月一次，連續三次以上均超過一．四三回復每六個月一次；連續六次以上均超過者得每年一次"],"a",
 "第84條之1第2項第1款：檢測申報或主管機關稽查採樣數據，任一次二種生物TUa值均超過一．四三時，應每三個月檢測申報一次；於數據累計連續三次以上二種生物TUa值均低於一．四三時，檢測及申報頻率回復為每六個月一次。第2款：累計連續六次以上二種生物TUa值均低於一．四三時，得調整為每年檢測申報一次。",
 "How does the acute toxicity reporting frequency adjust with TUa values?",
 ["Both species above 1.43 once: every three months; three consecutive rounds below 1.43: back to six months; six consecutive below: yearly","Both species above 1.43 once: every month; three consecutive rounds below 1.43: back to three months; six consecutive below: half yearly","Both species above 14.3 once: every three months; three consecutive rounds below 14.3: back to six months; six consecutive below: yearly","Both species below 1.43 once: every three months; three consecutive rounds above 1.43: back to six months; six consecutive above: yearly"],
 "Article 84-1 paragraph 2."),

(W,"第84條之2",3,"水措-毒性減量",
 "放流水生物急毒性連續六次數據中，累計幾次二種生物 TUa 值均超過一．四三時，主管機關得命執行毒性鑑定及減量程序？",
 ["累計三次水樣之二種生物TUa值均超過一．四三時，直轄市、縣（市）主管機關得命執行毒性鑑定及毒性減量程序並提報計畫備查","累計一次水樣之二種生物TUa值均超過一．四三時，直轄市、縣（市）主管機關得命執行毒性鑑定及毒性減量程序並提報計畫備查","累計六次水樣之二種生物TUa值均超過一．四三時，中央主管機關得命執行毒性鑑定及毒性減量程序並將計畫公告於指定網站","累計三次水樣之二種生物TUa值均低於一．四三時，直轄市、縣（市）主管機關得命執行毒性鑑定及毒性減量程序並提報備查"],"a",
 "第84條之2第1項：檢測申報或主管機關稽查採樣放流水生物急毒性連續六次數據中，累計三次水樣之二種生物TUa值均超過一．四三時，水質已具有生物急毒性之虞，直轄市、縣（市）主管機關得命其執行毒性鑑定及毒性減量程序，並提報毒性鑑定及毒性減量計畫備查。第4項並列明成果報告應包括基本資料、執行期間、廢水排放特性與急毒性檢測結果、鑑定與減量評估步驟及成效。",
 "How many of six consecutive rounds above TUa 1.43 trigger toxicity reduction?",
 ["Three sample rounds with both species above 1.43; the municipal or county authority may order identification and reduction and require a filed plan","One sample round with both species above 1.43; the municipal or county authority may order identification and reduction and require a filed plan","Six sample rounds with both species above 1.43; the central competent authority may order the procedure and publish the plan on its website","Three sample rounds with both species below 1.43; the municipal or county authority may order identification and reduction and require a filed plan"],
 "Article 84-2 paragraph 1."),

(W,"第84條之2",3,"水措-執行期限",
 "毒性鑑定及毒性減量程序之執行期間為何？得否展延？成果報告應於何時提送？",
 ["執行期間以二年為限，屆期無法完成得於屆滿前三十日申請展延一次，展延最長不超過兩年；屆滿後十五日內應提送成果報告","執行期間以五年為限，屆期無法完成得於屆滿前三十日申請展延二次，展延最長不超過兩年；屆滿後十五日內應提送成果報告","執行期間以二年為限，屆期無法完成得於屆滿前三日申請展延不限次數，展延最長不超過十年；屆滿後六個月內提送成果報告","執行期間以二年為限，屆期無法完成者一律不得申請展延須重新執行程序；屆滿後十五日內應提送成果報告予主管機關認定"],"a",
 "第84條之2第2項：毒性鑑定及毒性減量程序執行期間以二年為限，期間免依第84條規定檢測申報生物急毒性；屆期無法完成者得於屆滿前三十日向直轄市、縣（市）主管機關提出展延申請，展延申請以一次為限，展延期限最長不超過兩年。第3項：執行期間屆滿後十五日內應將成果報告提送直轄市、縣（市）主管機關認定，未於限期內提送或經認定未完成改善者予以處分。",
 "How long may the toxicity reduction procedure run, and when is the report due?",
 ["Two years, with one extension applied for 30 days before expiry and capped at two more years; the report is due within 15 days after expiry","Five years, with two extensions applied for 30 days before expiry and capped at two more years; the report is due within 15 days after expiry","Two years, with unlimited extensions applied for 3 days before expiry and capped at ten years; the report is due within 6 months after expiry","Two years, with no extension permitted so the procedure must restart entirely; the report is due within 15 days after expiry for determination"],
 "Article 84-2 paragraphs 2 and 3."),

(W,"第84條之3",3,"水措-新興關注",
 "經指定之事業依附表六辦理新興關注項目檢測，其數據連續二次超過規定數值者應如何辦理？",
 ["應於三個月內提出該項目之自主削減管理計畫送直轄市、縣（市）主管機關備查後據以執行；執行期間以二年為限","應於三個月內提出該項目之自主削減管理計畫送中央主管機關核准後據以執行；執行期間以五年為限並得展延","應於六個月內提出該項目之自主削減管理計畫送直轄市、縣（市）主管機關核准後執行；執行期間以十年為限","應於三日內提出該項目之自主削減管理計畫送直轄市、縣（市）主管機關備查後據以執行；執行期間並無限制"],"a",
 "第84條之3第2項：放流水檢測項目數據連續二次超過附表六規定數值者，應於三個月內提出該項目之自主削減管理計畫，送直轄市、縣（市）主管機關備查後據以執行；自主削減管理計畫執行期間以二年為限，該項目執行期間免依附表六規定檢測。第3項：執行期間屆滿後三十日內應提送改善情形報告。第4項：連續三次以上未超過規定數值者該項目得免檢測申報。",
 "What follows two consecutive exceedances of an emerging concern parameter?",
 ["Submit a self-reduction management plan for that parameter within three months for municipal or county filing; the programme runs at most two years","Submit a self-reduction management plan within three months for central competent authority approval; the programme runs five years and may be extended","Submit a self-reduction management plan within six months for municipal or county approval; the programme runs for at most ten years in total","Submit a self-reduction management plan within three days for municipal or county filing; there is no limit on how long the programme runs"],
 "Article 84-3 paragraphs 2 to 4."),

(W,"第85條",3,"水措-監測井",
 "採土壤處理者，其土壤處理土地總面積達一公頃以上未達二十五公頃者，應設置幾口地下水監測井？",
 ["應於地下水流之上、下游處各設置一口地下水監測井，並各採取一個土壤樣品；土壤採樣應採淺層混合樣品","應於地下水流之上、中、下游處各設置一口地下水監測井，並各採取一個土壤樣品；土壤採樣應採深層樣品","應於地下水流之上、下游中間處設置一口地下水監測井，並採取一個土壤樣品；土壤採樣應採淺層混合樣品","應設置五口以上地下水監測井並採取五個以上土壤樣品；監測井應於地下水流之上中下游及四週設置採取"],"a",
 "第85條第1項第2款：土壤處理土地總面積達一公頃以上未達二十五公頃者，應於地下水流之上、下游處各設置一口地下水監測井，各採取一個土壤樣品。第1款：未達一公頃者於上下游中間處設置一口井、採取一個樣品。第3款：達二十五公頃以上未達一百公頃者於上中下游處各設一口井、各採一個樣品。第2項：土壤採樣應採淺層混合樣品。",
 "For soil treatment land of 1 to under 25 hectares, how many monitoring wells are required?",
 ["One well each upgradient and downgradient of groundwater flow, with one soil sample each; soil samples are shallow composite samples","One well each upgradient, midgradient and downgradient of groundwater flow, with one soil sample each; soil samples are deep samples","One well midway between upgradient and downgradient of groundwater flow, with one soil sample; samples are shallow composite samples","Five or more wells with five or more soil samples; wells are placed upgradient, midgradient, downgradient and around the perimeter"],
 "Article 85 paragraph 1 subparagraph 2 and paragraph 2."),

(W,"第85條",3,"水措-大面積監測",
 "土壤處理土地總面積達一百公頃以上者，應如何設置地下水監測井及採取土壤樣品？",
 ["應設置五口以上之地下水監測井及採取五個以上土壤樣品，並於地下水流之上、中、下游及四週設置及採取","應設置三口以上之地下水監測井及採取三個以上土壤樣品，並於地下水流之上、中、下游及四週設置及採取","應設置五口以上之地下水監測井及採取五個以上土壤樣品，惟得由業者自行選定設置位置而不受限制拘束","應設置十口以上之地下水監測井及採取十個以上土壤樣品，並於地下水流之上、中、下游及四週設置採取"],"a",
 "第85條第1項第4款：土壤處理土地總面積達一百公頃以上者，應設置五口以上之地下水監測井及採取五個以上土壤樣品；其地下水監測井及土壤樣品應於地下水流之上、中、下游及四週設置及採取。第3項：主管機關得依地下水水文、水質狀況等實際需要，命增加地下水監測井及土壤採樣數量。",
 "For soil treatment land of 100 hectares or more, what monitoring is required?",
 ["At least five groundwater monitoring wells and five soil samples, placed upgradient, midgradient, downgradient and around the perimeter","At least three groundwater monitoring wells and three soil samples, placed upgradient, midgradient, downgradient and around the perimeter","At least five groundwater monitoring wells and five soil samples, with locations chosen freely by the operator without any restriction","At least ten groundwater monitoring wells and ten soil samples, placed upgradient, midgradient, downgradient and around the perimeter"],
 "Article 85 paragraph 1 subparagraph 4."),

(W,"第86條",3,"水措-申報頻率",
 "事業或污水下水道系統之基本申報頻率為何？應設專責單位或甲級專責人員且排放於地面水體者其頻率為何？",
 ["基本申報頻率為每六個月一次；應設專責單位或甲級專責人員且排放於地面水體者為每三個月申報一次","基本申報頻率為每三個月一次；應設專責單位或甲級專責人員且排放於地面水體者為每六個月申報一次","基本申報頻率為每六個月一次；應設專責單位或甲級專責人員且排放於地面水體者為每年申報一次即可","基本申報頻率為每年一次；應設專責單位或甲級專責人員且排放於地面水體者為每六個月申報一次即可"],"a",
 "第86條第1項：申報頻率為每六個月一次；但免設置廢（污）水處理專責人員之社區專用污水下水道系統每年申報一次，應設置廢（污）水處理專責單位或甲級廢（污）水處理專責人員之事業或污水下水道系統且其廢水排放於地面水體者每三個月申報一次，採土壤處理者其土壤樣品每年申報一次，以海放管排放廢水於海洋者每三個月申報一次。第2項：主管機關得命增加申報頻率。",
 "What is the base reporting frequency, and what applies to Class A units discharging to surface water?",
 ["Base frequency is every six months; those with a dedicated unit or Class A personnel discharging to surface water report every three months","Base frequency is every three months; those with a dedicated unit or Class A personnel discharging to surface water report every six months","Base frequency is every six months; those with a dedicated unit or Class A personnel discharging to surface water report once every year","Base frequency is once a year; those with a dedicated unit or Class A personnel discharging to surface water report every six months only"],
 "Article 86 paragraph 1."),

(W,"第86條",2,"水措-特殊頻率",
 "免設置廢水處理專責人員之社區專用污水下水道系統、採土壤處理之土壤樣品、以海放管排放者，其申報頻率各為何？",
 ["社區專用污水下水道系統每年申報一次；土壤處理之土壤樣品每年申報一次；以海放管排放於海洋者每三個月申報一次","社區專用污水下水道系統每季申報一次；土壤處理之土壤樣品每季申報一次；以海放管排放於海洋者每六個月申報一次","社區專用污水下水道系統每年申報一次；土壤處理之土壤樣品每月申報一次；以海放管排放於海洋者每年申報一次即可","社區專用污水下水道系統每六個月申報一次；土壤處理之土壤樣品每三個月申報一次；以海放管排放者每年申報一次"],"a",
 "第86條第1項第1款、第3款、第4款：免設置廢（污）水處理專責人員之社區專用污水下水道系統每年申報一次；採土壤處理者其土壤樣品每年申報一次；以海放管排放廢（污）水於海洋者每三個月申報一次。第93條並就各類對象之申報期間（每年一月底前申報前一年七月至十二月資料等）另有詳細規定。",
 "What frequencies apply to community sewers, soil samples and sea outfalls?",
 ["Community dedicated sewers report yearly; soil treatment soil samples yearly; sea outfall dischargers every three months","Community dedicated sewers report quarterly; soil treatment soil samples quarterly; sea outfall dischargers every six months","Community dedicated sewers report yearly; soil treatment soil samples monthly; sea outfall dischargers once every year only","Community dedicated sewers report every six months; soil treatment soil samples quarterly; sea outfall dischargers yearly"],
 "Article 86 paragraph 1 subparagraphs 1, 3 and 4."),

(W,"第87條",2,"水措-總量管制",
 "事業位於總量管制區內且設有自動監測系統，中央主管機關對自動監測項目有連線作業規定者，其申報應如何辦理？",
 ["其申報內容、格式及頻率依中央主管機關之規定辦理","其申報內容、格式及頻率仍依附表一及第八十六條辦理","其申報內容、格式及頻率由事業與主管機關個案協商定之","其申報內容、格式及頻率依目的事業主管機關公告辦理"],"a",
 "第87條：事業或污水下水道系統位於總量管制區內，設有自動監測系統，且中央主管機關對自動監測項目有連線作業規定者，其申報內容、格式及頻率依中央主管機關之規定。第108條第2項並規定符合自動監測傳輸規定者，辦理本法規定之申報時得以傳輸之水質水量資料為之。",
 "How does an enterprise in a total quantity control zone with online monitoring report?",
 ["Its reporting content, format and frequency follow the central competent authority's rules","Its reporting content, format and frequency still follow Table 1 and Article 86 as usual","Its reporting content, format and frequency are negotiated case by case with the authority","Its reporting content, format and frequency follow the industry authority's announcement"],
 "Article 87."),

(W,"第88條",2,"水措-分別申報",
 "事業同時採行二種以上水措者，及共同設置廢水處理設施處理者，應如何申報？",
 ["同時採行二種以上水措者應分別申報；共同設置廢（污）水（前）處理設施處理者應共同辦理申報","同時採行二種以上水措者應合併申報；共同設置廢（污）水（前）處理設施處理者應分別辦理申報","同時採行二種以上水措者應擇一申報即可；共同設置廢（污）水（前）處理設施者由主辦事業申報","同時採行二種以上水措者應分別申報；共同設置廢（污）水（前）處理設施者由各事業分別申報"],"a",
 "第88條第1項：事業或污水下水道系統同時採行二種以上水措者，應分別申報。第2項：事業或污水下水道系統共同設置廢（污）水（前）處理設施處理者，應共同辦理申報。第2條第2款並定義共同設置廢（污）水（前）處理設施為二以上事業合資共同興建並使用。",
 "How must multiple measures and jointly built facilities be reported?",
 ["Two or more measures adopted at once are reported separately; jointly built treatment facilities are reported jointly","Two or more measures adopted at once are reported together; jointly built treatment facilities are reported separately","Two or more measures adopted at once need only one report; jointly built facilities are reported by the lead enterprise","Two or more measures adopted at once are reported separately; jointly built facilities are reported by each enterprise alone"],
 "Article 88."),

(W,"第89條",1,"水措-同日採樣",
 "事業或污水下水道系統申報之水質、水量，其採樣及量測時間有何規定？",
 ["應於同一日採樣及量測，但逕流廢水之水質、水量不在此限","應於同一日採樣及量測，且逕流廢水之水質水量亦無例外","應於同一週內採樣及量測，但逕流廢水之水質水量不在此限","應於同一個月內採樣及量測，但原廢水之水質水量不在此限"],"a",
 "第89條：事業或污水下水道系統申報之水質、水量，應於同一日採樣及量測；但逕流廢水之水質、水量，不在此限。第90條並列有得免委託環境檢驗測定機構辦理之水質水量情形，例如原廢水水質及水量、回收使用之水量、逕流廢水水質及水量等。",
 "When must reported water quality and quantity be sampled and measured?",
 ["On the same day, except for runoff wastewater quality and quantity","On the same day, with no exception even for runoff wastewater","Within the same week, except for runoff wastewater quality and quantity","Within the same month, except for raw wastewater quality and quantity"],
 "Article 89."),
]
